{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "GSK2838232, a complex triterpenoid-like molecule with a large lipophilic scaffold and polar substituents, showed poor oral bioavailability in initial clinical studies, supporting low F for the query's analogous pentacyclic triterpenoid core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Oleanolic acid, a pentacyclic triterpenoid acid, showed poor oral bioavailability in healthy volunteers after a 20 mg tablet, directly supporting low absorption for triterpenoid acid scaffolds similar to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Glycyrrhizin, a triterpenoid acid derivative, has an absolute oral bioavailability of approximately 0.25% in humans, indicating that large, polar triterpenoid acids tend to have very low oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Anecortave desacetate, a steroid-like molecule, demonstrated low oral bioavailability in a human 14C study, consistent with poor absorption of large lipophilic cyclopentanophenanthrene-type scaffolds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "DJ-927, a taxane, was reported to have high oral bioavailability, but its taxane scaffold and ester-linked side chain are structurally distant from the query's triterpenoid acid, so this high-F evidence has limited transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a large, highly lipophilic zwitterionic pentacyclic triterpenoid acid derivative. Closest experimental analogs—triterpenoid acids such as oleanolic acid and glycyrrhizin—show poor to extremely low oral bioavailability, and a structurally similar triterpenoid-like clinical candidate (GSK2838232) was also poorly bioavailable. High-bioavailability comparators are structurally distant small molecules or taxanes and do not override this evidence. Therefore F is predicted below 20%.",
  "evidence_gaps": [
    "No direct human or animal pharmacokinetic data for the query molecule.",
    "No formulation, salt form, or solubility/permeability measurements for the query.",
    "No data on transporter-mediated absorption or efflux for the query.",
    "No dose-ranging or food-effect data that could alter oral bioavailability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

